namespace Minto.Api.Domain;
public enum OrderStatus { Placed, Picking, Picked, Packed, ReadyForPickup, Assigned, Accepted, OutForDelivery, Delivered, Cancelled }
public sealed class Product { public Guid Id { get; set; } = Guid.NewGuid(); public required string Name { get; set; } public required string Category { get; set; } public decimal Price { get; set; } public bool IsActive { get; set; } }
public sealed class InventoryItem { public Guid ProductId { get; set; } public int Available { get; set; } public int Reserved { get; set; } public long Version { get; set; } }
public sealed class Order { public Guid Id { get; set; } = Guid.NewGuid(); public required string CustomerId { get; set; } public required string Address { get; set; } public OrderStatus Status { get; set; } = OrderStatus.Placed; public string PaymentMethod { get; set; } = "COD"; public bool PaymentCompleted { get; set; } public decimal Total { get; set; } public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow; public string? StoreId { get; set; } public string? PickerId { get; set; } public string? RiderId { get; set; } public string? PickupCode { get; set; } public string? DeliveryOtp { get; set; } public DateTimeOffset? DeliveryDeadline { get; set; } public bool IsPriority { get; set; } public string? IdempotencyKey { get; set; } public List<OrderLine> Lines { get; set; } = []; }
public sealed class OrderLine { public Guid Id { get; set; } = Guid.NewGuid(); public Guid OrderId { get; set; } public Guid ProductId { get; set; } public required string ProductName { get; set; } public int Quantity { get; set; } public int PickedQuantity { get; set; } public decimal UnitPrice { get; set; } }
public sealed class Cart { public Guid Id { get; set; } = Guid.NewGuid(); public required string CustomerId { get; set; } public DateTimeOffset UpdatedAt { get; set; } = DateTimeOffset.UtcNow; public List<CartLine> Lines { get; set; } = []; }
