public sealed class OutboxMessage { public Guid Id { get; set; } = Guid.NewGuid(); public required string EventType { get; set; } public required string Payload { get; set; } public DateTimeOffset OccurredAt { get; set; } = DateTimeOffset.UtcNow; public bool Published { get; set; } }

public enum ReviewStatus { Pending, Approved, Rejected }
public enum ReplacementStatus { Proposed, Approved, Rejected }
public enum ComplaintStatus { Open, InProgress, Resolved, Rejected }
public enum AttendanceStatus { Scheduled, CheckedIn, CheckedOut, Absent }

public sealed class RiderProfile { public string Id { get; set; } = ""; public required string Name { get; set; } public string Phone { get; set; } = ""; public string Vehicle { get; set; } = ""; public ReviewStatus KycStatus { get; set; } public DateTimeOffset? KycReviewedAt { get; set; } public string? KycReviewedBy { get; set; } public bool IsOnline { get; set; } public bool IsSuspended { get; set; } }
public sealed class KycDocument { public Guid Id { get; set; } = Guid.NewGuid(); public required string RiderId { get; set; } public required string Type { get; set; } public required string DocumentReference { get; set; } public ReviewStatus Status { get; set; } = ReviewStatus.Pending; public DateTimeOffset SubmittedAt { get; set; } = DateTimeOffset.UtcNow; }
